create or replace function public.send_prioritized_notification_batch(p_business_id uuid,p_user_ids uuid[],p_title text,p_message text,p_priority text default 'high',p_metadata jsonb default '{}'::jsonb) returns integer language plpgsql security invoker set search_path=public,pg_temp as $$ declare v_count integer:=0; v_user uuid; begin if p_user_ids is null or cardinality(p_user_ids)=0 then raise exception 'At least one target user is required'; end if; foreach v_user in array p_user_ids loop perform public.send_prioritized_notification('fleet',p_business_id,v_user::text,p_title,p_message,p_priority,p_metadata);v_count:=v_count+1;end loop;return v_count; end; $$; grant execute on function public.send_prioritized_notification_batch(uuid,uuid[],text,text,text,jsonb) to authenticated;
